def transform(grid):
    h, w = len(grid), len(grid[0])

    # Divider lines span the full grid and use a single color.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(n, dividers):
        parts = []
        start = 0
        for d in dividers:
            if start < d:
                parts.append((start, d))
            start = d + 1
        if start < n:
            parts.append((start, n))
        return parts

    row_parts = intervals(h, divider_rows)
    col_parts = intervals(w, divider_cols)

    # Find the background and the scattered object color, ignoring dividers.
    from collections import Counter
    divider_cells = set()
    for r in divider_rows:
        divider_cells.update((r, c) for c in range(w))
    for c in divider_cols:
        divider_cells.update((r, c) for r in range(h))
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if (r, c) not in divider_cells)
    background = counts.most_common(1)[0][0]
    object_color = next(color for color, _ in counts.most_common() if color != background)

    result = []
    for r0, r1 in row_parts:
        row = []
        for c0, c1 in col_parts:
            count = sum(grid[r][c] == object_color
                        for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if count == 2 else background)
        result.append(row)
    return result
